<script setup>
import { computed, onUnmounted, ref, watch } from 'vue'
import ProcessDesigner from '../ProcessDesigner.vue'
import UiIcon from '../UiIcon.vue'
import { approvalNodes, participants, pendingParticipants } from '../process.js'
import { createScenarioApi } from './scenario-api.js'
import { createScenarioWorkspace } from './scenario-workspace.js'
import { formatExpenseMoney } from './expense-document.js'
import ScenarioForm from './ScenarioForm.vue'
import { getScenarioHandler } from './scenario-registry.js'
import ScenarioDetail from './ScenarioDetail.vue'
const props = defineProps({ api: { type: Object, default: null } })
const workspace = createScenarioWorkspace(props.api || createScenarioApi()), s = workspace.state
const locale = ref('en'), username = ref('alice'), password = ref('')
const zh = computed(() => locale.value === 'zh')
watch(locale, value => { document.documentElement.lang = value === 'zh' ? 'zh-CN' : 'en' }, { immediate: true })
onUnmounted(() => workspace.dispose())
const handler = computed(() => getScenarioHandler(s.activeScenarioId))
const travel = computed(() => handler.value.documentType === 'travel')
const newLabel = computed(() => travel.value ? (zh.value ? '新建出差' : 'New travel request') : (zh.value ? '新建报销' : 'New expense'))
const scenarioKicker = computed(() => travel.value ? (zh.value ? '出差申请' : 'BUSINESS TRAVEL') : (zh.value ? '费用报销' : 'EXPENSE REIMBURSEMENT'))
const template = computed(() => s.catalog.find(entry => entry.id === handler.value.id))
const name = id => { const person = s.people.find(person => person.id === id); return person?.displayName || person?.name || id }
const money = (value, currency) => formatExpenseMoney(value, currency)
const mine = computed(() => s.items.filter(view => view.request.applicantId === s.me?.id))
const review = computed(() => s.items.filter(view => pendingParticipants(view.request).includes(s.me?.id)))
const handled = computed(() => s.items.filter(view => view.request.history.some(event => event.actorId === s.me?.id && ['APPROVE', 'REJECT'].includes(event.action))))
const retained = computed(() => s.items.filter(view => workspace.retainedNotesFor(view.request.id).length))
const retainedCount = computed(() => Object.keys(s.retainedNotes).length)
const visible = computed(() => s.tab === 'retained' ? retained.value : s.tab === 'review' ? review.value : s.tab === 'handled' ? handled.value : mine.value)
// Keep each scene's in-progress review when navigating, but render its detail
// only when the saved selection belongs to the currently displayed worklist.
const selected = computed(() => visible.value.find(view => view.request.id === s.selectedId))
const status = value => ({ PENDING: zh.value ? '审批中' : 'Pending', APPROVED: zh.value ? '已通过' : 'Approved', REJECTED: zh.value ? '已驳回' : 'Rejected' })[value]
const tabs = computed(() => [
  { id: 'new', label: newLabel.value, icon: 'requests' },
  { id: 'mine', label: zh.value ? '我的申请' : 'My requests', icon: 'requests', count: mine.value.length },
  { id: 'review', label: zh.value ? '待我审批' : 'Needs my review', icon: 'review', count: review.value.length },
  { id: 'handled', label: zh.value ? '我的审批记录' : 'My decisions', icon: 'review', count: handled.value.length },
  ...(retained.value.length ? [{ id: 'retained', label: zh.value ? '保留的说明' : 'Retained notes', icon: 'requests', count: retained.value.length }] : []),
  { id: 'designer', label: zh.value ? '审批流程' : 'Approval process', icon: 'process' },
])
const currentTitle = computed(() => tabs.value.find(tab => tab.id === s.tab)?.label || (zh.value ? '场景库' : 'Scenario library'))
function openScenario(id) { return workspace.selectScenario(id) }
function requestSummary(business) { return business.type === 'travel' ? `${business.destination} · ${getScenarioHandler('oa-travel').duration(business)} ${zh.value ? '天' : 'days'}` : `${business.lines.length} ${zh.value ? '项费用' : 'expense lines'}` }
function navigate(tab) { s.tab = tab }
function selectRequest(id) { if (id !== s.selectedId) workspace.select(id) }
function openRetained() { navigate('retained'); if (!selected.value && retained.value.length) selectRequest(retained.value[0].request.id) }
function dismissNote(id, stepId) {
  workspace.dismissRetainedNote(id, stepId)
  if (s.tab === 'retained' && !workspace.retainedNotesFor(id).length) {
    if (retained.value.length) selectRequest(retained.value[0].request.id)
    else navigate('review')
  }
}
async function login() { if (s.busy) return; const secret = password.value; password.value = ''; await workspace.login(username.value, secret) }
const errorText = computed(() => {
  if (!s.error) return ''
  if (s.error.operation === 'decision' && s.error.cause?.code === 'DECISION_COMMENT_MISMATCH') {
    return zh.value ? '保存的审批说明与本次提交不一致，你填写的说明已保留。请更新数据，核对已保存的审批记录后再继续。' : 'The saved comment did not match this decision. Your typed note is retained. Refresh to inspect the saved audit before continuing.'
  }
  if (s.error.operation === 'decision' && s.error.cause?.code === 'DECISION_RECOVERY_MISMATCH') {
    return zh.value ? '已保存的记录未确认你本次提交的审批与说明。原说明已按原节点保留，请更新数据后再继续。' : 'Saved activity did not confirm your submitted decision and note. Your note is retained with its original step. Refresh before continuing.'
  }
  const en = { login: 'Sign-in could not be completed. Check the account, server-configured password and backend, then try again.', validation: 'Check the highlighted fields before submitting.', selfAssigned: 'The applicant cannot also review this request. Alice can adjust the published approval process.', refresh: 'Refresh failed. Existing data and your draft are preserved. Try Refresh again.', publish: 'Publication was not confirmed. Your draft is preserved. Refresh, reset to the latest process, then reapply your edits before publishing.', submit: s.rejectedVersion ? 'The published process changed. Refresh to load the new version before submitting.' : 'Submission was not confirmed. Check My requests, or retry the unchanged form with its original key and process version. Editing the form creates a new request intent.', decision: 'The decision was not confirmed. We checked for saved results. If actions remain locked, use Refresh before deciding again.' }
  const cn = { login: '登录未完成。请检查账号、服务端设置的密码及后端服务，然后重试。', validation: '请检查高亮字段后再提交。', selfAssigned: '申请人不能审批自己的申请。Alice 可调整已发布的流程。', refresh: '数据更新失败。现有数据与草稿已保留，请再次点击更新数据。', publish: '发布结果未确认，草稿已保留。请更新数据，重置为最新流程，再重新应用修改后发布。', submit: s.rejectedVersion ? '已发布流程发生变化。请更新数据后再提交。' : '提交结果未确认。请检查我的申请，或保持表单不变，以原提交标识与流程版本重试。修改表单会创建新的申请意图。', decision: '审批结果未确认，已尝试读取已保存结果。如操作仍被锁定，请先更新数据再审批。' }
  return (zh.value ? cn : en)[s.error.operation] || (zh.value ? '操作失败，请重试。' : 'The operation failed. Try again.')
})
const noticeText = computed(() => ({ refreshed: zh.value ? '数据已更新，本地修改已保留。' : 'Data refreshed. Local edits are preserved.', submitted: travel.value ? (zh.value ? '出差申请已保存，审批流程已启动。' : 'Travel request saved. Its approval process has started.') : (zh.value ? '报销申请已保存，审批流程已启动。' : 'Expense request saved. Its approval process has started.'), published: zh.value ? `流程 v${s.process?.version} 已发布，既有申请保留原快照。` : `Process v${s.process?.version} published. Existing requests keep their snapshots.`, decided: selected.value ? (zh.value ? '审批意见已保存，以下为最新结果。' : 'Your decision is saved. The latest result is shown below.') : (zh.value ? '审批意见已保存，可在我的审批记录中查看结果。' : 'Your decision is saved. Find the result in My decisions.') })[s.notice])
</script>
<template>
  <div v-if="!s.me" class="sf-login" :lang="zh ? 'zh-CN' : 'en'">
    <section class="sf-login-story"><div class="wordmark"><span class="logo">a</span>ArcFlow<span class="sf-product-tag">SCENARIOS</span></div><div><p class="sf-kicker">{{ zh ? '从业务出发，让审批自然发生' : 'BUSINESS FIRST. FLOW FOLLOWS.' }}</p><h1>{{ zh ? '每个场景，' : 'Every detail.' }}<br>{{ zh ? '都有清晰的流程。' : 'A clearer flow.' }}</h1><p>{{ zh ? '从费用明细到出差行程，用独立业务表单与可复用流程，看清每一步。' : 'From itemized expenses to business travel. Distinct forms, reusable approval processes, and every decision in context.' }}</p><div class="sf-login-path"><span>01<br><b>{{ zh ? '填写申请' : 'Prepare' }}</b></span><i>→</i><span>02<br><b>{{ zh ? '逐级审批' : 'Review' }}</b></span><i>→</i><span>03<br><b>{{ zh ? '追溯记录' : 'Trace' }}</b></span></div></div><small>{{ zh ? '仅本地合成数据演示 · 审批通过不会发起付款' : 'Local synthetic-data demo · approval does not issue payment' }}</small></section>
    <section class="sf-login-panel"><label class="sf-language"><span class="sr-only">Language / 语言</span><select v-model="locale" aria-label="Language / 语言"><option value="en">English</option><option value="zh">中文</option></select></label><form class="sf-login-form" @submit.prevent="login"><p class="sf-kicker">{{ zh ? 'ARCFLOW 场景库' : 'ARCFLOW SCENARIO LIBRARY' }}</p><h2>{{ zh ? '进入工作空间' : 'Enter your workspace' }}</h2><p class="muted">{{ zh ? '使用服务端配置的演示账号与密码。' : 'Use a demo account and its server-configured password.' }}</p><label>{{ zh ? '演示账号' : 'Demo account' }}<select v-model="username" :disabled="s.busy"><option value="alice">Alice · {{ zh ? '申请人 / 流程管理员' : 'Applicant / process editor' }}</option><option value="bob">Bob · {{ zh ? '业务审核' : 'Business reviewer' }}</option><option value="carol">Carol · {{ zh ? '费用 / 预算复核' : 'Finance / budget reviewer' }}</option></select></label><label>{{ zh ? '密码' : 'Password' }}<input v-model="password" type="password" autocomplete="off" :disabled="s.busy" required></label><p v-if="s.error" class="error" role="alert">{{ errorText }}</p><button class="primary full" type="submit" :disabled="s.busy">{{ s.busy ? (zh ? '正在登录…' : 'Signing in…') : (zh ? '进入场景库' : 'Open scenario library') }} →</button><p class="sf-login-note">{{ zh ? '账号凭据仅保存在本标签页内存中。退出或刷新网页会清除未保存草稿。' : 'Credentials stay in this tab’s memory. Sign-out or browser reload clears unsaved drafts.' }}</p></form></section>
  </div>
  <div v-else class="sf-shell" :lang="zh ? 'zh-CN' : 'en'">
    <aside class="sf-sidebar"><div class="wordmark"><span class="logo">a</span>ArcFlow</div><div class="sf-sidebar-title">{{ zh ? '工作空间' : 'WORKSPACE' }}</div><nav :aria-label="zh ? '主导航' : 'Main navigation'"><button :class="{ active: s.tab === 'catalog' }" data-testid="catalog-tab" @click="navigate('catalog')"><span class="sf-grid-icon" aria-hidden="true">▦</span>{{ zh ? '场景库' : 'Scenario library' }}<small>{{ String(s.catalog.length).padStart(2, '0') }}</small></button><p>{{ template.domain }} · {{ template.title[locale] }}</p><button v-for="tab in tabs" :key="tab.id" :data-testid="`${tab.id}-tab`" :class="{ active: s.tab === tab.id }" @click="navigate(tab.id)"><UiIcon :name="tab.icon" />{{ tab.label }}<small v-if="tab.count !== undefined">{{ tab.count }}</small></button></nav><div class="sf-sidebar-bottom"><span class="sf-synthetic-dot"></span><span>{{ zh ? '合成数据工作空间' : 'Synthetic workspace' }}</span><p>{{ zh ? '数据计数仅代表已加载记录。' : 'Counts reflect loaded records.' }}</p></div><div class="sf-person"><span>{{ name(s.me.id).charAt(0) }}</span><div><strong>{{ name(s.me.id) }}</strong><small>{{ s.me.id === 'alice' ? (zh ? '申请人 · 流程管理员' : 'Applicant · editor') : (zh ? '审批人' : 'Reviewer') }}</small></div><button type="button" :aria-label="zh ? '退出登录' : 'Sign out'" data-testid="scenario-logout" @click="workspace.logout"><UiIcon name="logout" /></button></div></aside>
    <main class="sf-main"><header class="sf-topbar"><div><span>ArcFlow</span><i>/</i><strong>{{ currentTitle }}</strong></div><div class="sf-topbar-actions"><label class="sf-language"><span class="sr-only">Language / 语言</span><select v-model="locale" aria-label="Language / 语言"><option value="en">English</option><option value="zh">中文</option></select></label><button class="secondary" data-testid="scenario-refresh" :disabled="s.busy" @click="workspace.refresh">↻ <span>{{ zh ? '更新数据' : 'Refresh' }}</span></button><button class="secondary sf-mobile-logout" type="button" :aria-label="zh ? '退出登录' : 'Sign out'" @click="workspace.logout"><UiIcon name="logout" /></button></div></header>
      <div class="sf-content"><div v-if="s.error" class="error sf-alert" role="alert"><strong>{{ errorText }}</strong><details v-if="s.error.cause?.message"><summary>{{ zh ? '原始服务信息' : 'Original service detail' }}</summary>{{ s.error.cause.message }}</details></div><p v-if="s.notice" class="notice" role="status">{{ noticeText }}</p><button v-if="retainedCount" type="button" class="sf-retained-index" data-testid="retained-notes-summary" @click="openRetained"><span>{{ retainedCount }} {{ zh ? '条未确认说明已保留在当前会话' : 'unconfirmed notes retained in this session' }}</span><strong>{{ zh ? '查看说明' : 'Review notes' }} →</strong></button>
        <section v-if="s.tab === 'catalog'" class="sf-catalog"><div class="sf-page-title"><p class="sf-kicker">{{ zh ? '可复用的业务场景' : 'REUSABLE BUSINESS SCENARIOS' }}</p><h1>{{ zh ? '从业务场景，开始审批。' : 'Start with the work.' }}</h1><p>{{ zh ? '业务表单、审批流程与完整记录，在一个场景中协同。' : 'Business forms, approval processes and a complete record. Together in one scenario.' }}</p></div><div class="sf-catalog-filter"><span>{{ zh ? '全部场景' : 'All scenarios' }} <b>{{ s.catalog.length }}</b></span><small>{{ zh ? 'OA · 办公自动化' : 'OA · Office automation' }}</small><small class="sf-local-badge">{{ zh ? '仅本地演示' : 'LOCAL DEMO' }}</small></div><article v-for="(entry, index) in s.catalog" :key="entry.id" class="sf-template-card"><div class="sf-template-art" :class="{ 'sf-travel-art': entry.documentType === 'travel' }" aria-hidden="true"><div v-if="entry.documentType === 'travel'" class="sf-itinerary"><span>BUSINESS TRAVEL</span><strong>{{ zh ? '出差计划' : 'A clear itinerary' }}</strong><div><b>01</b><span>{{ zh ? '目的地' : 'Destination' }}<i>{{ zh ? '项目交付' : 'Project delivery' }}</i></span></div><div><b>02</b><span>{{ zh ? '行程与预算' : 'Dates & budget' }}<i>{{ zh ? '审批前清晰呈现' : 'Ready for review' }}</i></span></div></div><div v-else class="sf-receipt"><span>EXPENSE REPORT</span><strong>3 {{ zh ? '笔费用' : 'line items' }}</strong><i></i><i></i><i></i><div><span>TOTAL</span><b>1,280.50</b></div></div><div class="sf-art-stamp">✓</div><div class="sf-art-label">{{ entry.documentType === 'travel' ? (zh ? '行程 → 预算 → 审批' : 'Plan → Budget → Review') : (zh ? '明细 → 审核 → 记录' : 'Itemize → Review → Trace') }}</div></div><div class="sf-template-info"><div class="sf-card-meta"><span>OA</span><small>{{ zh ? '模板' : 'TEMPLATE' }} {{ String(index + 1).padStart(2, '0') }} · v{{ entry.formVersion }}</small></div><h2>{{ entry.title[locale] }}</h2><p>{{ entry.description[locale] }}</p><div class="sf-tags"><span>{{ entry.documentType === 'travel' ? (zh ? '行程与预算' : 'Itinerary & budget') : (zh ? '多行费用' : 'Itemized expenses') }}</span><span>{{ zh ? '顺序审批' : 'Sequential review' }}</span><span>{{ zh ? '不可变快照' : 'Saved snapshots' }}</span></div><footer><span>{{ entry.documentType === 'travel' ? (zh ? '5 个币种 · 1–90 天行程' : '5 currencies · 1–90 day trips') : (zh ? '5 个币种 · 最多 20 项费用' : '5 currencies · up to 20 expense lines') }}</span><button class="primary" :data-testid="`open-${entry.documentType}`" @click="openScenario(entry.id)">{{ zh ? '使用此场景' : 'Use scenario' }} →</button></footer></div></article><div class="sf-pattern-row"><div><span>01</span><h3>{{ zh ? '业务先行' : 'Built around the document' }}</h3><p>{{ zh ? '报销明细与出差行程各有独立表单、草稿和业务规则。' : 'Expense lines and travel plans each have their own form, draft and business rules.' }}</p></div><div><span>02</span><h3>{{ zh ? '流程可复用' : 'One reusable approval flow' }}</h3><p>{{ zh ? '固定阶段支持单人、ALL 与 ANY 审批，表单与流程各自演进。' : 'Ordered stages support single, ALL and ANY review. The form and process can evolve separately.' }}</p></div><div><span>03</span><h3>{{ zh ? '每一步可追溯' : 'Every decision in context' }}</h3><p>{{ zh ? '提交时保存业务与流程快照，后续流程修改不影响已提交申请。' : 'Business data and process are snapshotted at submission, so later edits do not change existing requests.' }}</p></div></div></section>
        <template v-if="s.tab === 'new'"><div class="sf-page-title sf-title-row"><div><p class="sf-kicker">OA / {{ scenarioKicker }}</p><h1>{{ travel ? (zh ? '让行程与预算，一目了然。' : 'A clear plan before the trip.') : (zh ? '一份清晰的报销申请。' : 'A clear account of every expense.') }}</h1><p>{{ travel ? (zh ? '填写目的地、日期、用途与预计费用。所有字段均为必填。' : 'Add the destination, dates, purpose and estimated cost. All fields are required.') : (zh ? '填写费用与用途，审批人可以查看每一项。所有字段均为必填。' : 'Add the expenses and their purpose. Reviewers see every line. All fields are required.') }}</p></div><span class="sf-version-tag">{{ zh ? '表单' : 'FORM' }} v{{ template.formVersion }}</span></div><p v-if="s.uncertainSubmission" class="warning">{{ zh ? '上次提交结果不确定。原提交标识仍保留；修改表单前，请先检查我的申请。' : 'The last submission is uncertain. Its retry key is retained. Check My requests before editing the form.' }}</p><div class="sf-create-layout"><ScenarioForm :key="s.activeScenarioId" :template="template" :handler="handler" :model-value="s.form" :locale="locale" :errors="handler.errors(s.form)" :attempted="s.attempted" :busy="s.busy || !s.loaded" :retrying="s.uncertainSubmission" :rejected-version="s.rejectedVersion" @update:model-value="workspace.setForm" @submit="workspace.submit" /><aside class="sf-context-card"><p class="sf-kicker">{{ zh ? '本次审批路径' : 'THIS REQUEST’S ROUTE' }}</p><h2>{{ zh ? '提交后，接下来是…' : 'What happens next' }}</h2><ol class="sf-mini-flow"><li class="sf-mini-start"><span>↗</span><div><strong>{{ name(s.me.id) }}</strong><small>{{ travel ? (zh ? '提交出差申请' : 'Submits the travel request') : (zh ? '提交报销申请' : 'Submits the expense request') }}</small></div></li><li v-for="(node, index) in approvalNodes(workspace.submissionDefinition())" :key="node.id"><span>{{ index + 1 }}</span><div><strong>{{ node.name }}</strong><small>{{ participants(node).map(name).join(' + ') }}<template v-if="node.completionMode"> · {{ node.completionMode }}</template></small></div></li><li class="sf-mini-end"><span>✓</span><div><strong>{{ zh ? '审批完成' : 'Review complete' }}</strong><small>{{ zh ? '保留完整审批记录' : 'A complete decision trail' }}</small></div></li></ol><div class="sf-context-note"><strong>{{ zh ? '流程快照' : 'Process snapshot' }} v{{ workspace.submissionDefinition()?.version }}</strong><p>{{ travel ? (zh ? '提交时保存此流程、行程与预算。审批通过不会预订、报销或付款。' : 'This process, itinerary and budget are saved together. Approval does not book travel, reimburse expenses or issue a payment.') : (zh ? '提交时保存此流程与费用明细。通过审批仅结束演示流程，不发起付款。' : 'This process and the expense lines are saved together at submission. Approval completes the demo; it does not issue a payment.') }}</p></div><p class="sf-local-note">{{ travel ? (zh ? '仅填写合成行程。没有预订、通知或外部系统写回。' : 'Use synthetic itineraries only. No booking, notifications or external writeback.') : (zh ? '仅填写合成数据。没有发票上传、汇率换算或外部集成。' : 'Use synthetic data only. No receipt uploads, currency conversion or external integrations.') }}</p></aside></div></template>
        <section v-if="['mine', 'review', 'handled', 'retained'].includes(s.tab)"><div class="sf-page-title sf-title-row"><div><p class="sf-kicker">OA / {{ scenarioKicker }}</p><h1>{{ currentTitle }}</h1><p>{{ s.tab === 'retained' ? (zh ? '这些说明保留在原申请与原节点中。可复制或清除本地说明，退出登录时会清除。' : 'These notes remain attached to their original request and stage. Copy or dismiss them here; sign-out clears them.') : s.tab === 'review' ? (zh ? '只显示当前节点仍需要你审批的申请。' : 'Requests that still need your decision on their current stage.') : s.tab === 'handled' ? (zh ? '你已保存过审批意见的申请，可能仍在流转。' : 'Requests with your saved decisions. Some may still be in progress.') : (zh ? '你提交的申请，以及每一步的最新状态。' : 'Your requests and the latest state of every step.') }}</p></div><button v-if="s.tab === 'mine'" class="primary" @click="navigate('new')">＋ {{ newLabel }}</button></div><div class="sf-record-layout"><section class="sf-request-list" :aria-label="currentTitle"><header><strong>{{ visible.length }} {{ zh ? '条已加载记录' : 'loaded records' }}</strong></header><div v-if="!visible.length" class="sf-empty"><UiIcon :name="s.tab === 'review' ? 'review' : 'requests'" /><h2>{{ zh ? '目前没有申请' : 'Nothing here yet' }}</h2><p>{{ s.tab === 'review' ? (zh ? '需要你审批的申请会显示在这里。' : 'Requests needing your review will appear here.') : (zh ? '申请与审批记录会显示在这里。' : 'Your requests and decisions will appear here.') }}</p></div><button v-for="view in visible" :key="view.request.id" type="button" class="sf-request-item" :class="{ selected: s.selectedId === view.request.id }" :aria-pressed="s.selectedId === view.request.id" @click="selectRequest(view.request.id)"><div><span class="sf-status" :class="view.request.status.toLowerCase()">{{ status(view.request.status) }}</span><small>{{ view.request.business.businessId }}</small></div><strong>{{ view.request.title }}</strong><p>{{ name(view.request.applicantId) }} · {{ requestSummary(view.request.business) }}</p><footer><b>{{ money(view.total, view.request.business.currency) }}</b><span>→</span></footer></button></section><ScenarioDetail :key="`${s.activeScenarioId}-${s.selectedId}`" v-if="selected" :view="selected" :template="template" :locale="locale" :people="s.people" v-model:comment="s.comment" :busy="s.busy" :can-decide="workspace.canDecide(selected)" :blocked="s.blockedDecisions.includes(selected.request.id)" :retained-notes="workspace.retainedNotesFor(selected.request.id)" @dismiss-note="dismissNote(selected.request.id, $event)" @decide="workspace.decide" /><div v-else class="sf-detail-placeholder"><div class="sf-placeholder-symbol">↗</div><h2>{{ travel ? (zh ? '每一段行程，都有目的。' : 'Every trip has a purpose.') : (zh ? '每一项费用，都有上下文。' : 'Every expense has a story.') }}</h2><p>{{ zh ? '选择申请，查看业务快照、保存的流程与完整审批记录。' : 'Select a request to see its business snapshot, saved process and complete decision trail.' }}</p></div></div></section>
        <section v-show="s.tab === 'designer'" class="sf-designer-section"><div class="sf-page-title"><p class="sf-kicker">OA / {{ zh ? '流程设计' : 'PROCESS DESIGN' }}</p><h1>{{ zh ? '清晰的责任，逐步推进。' : 'Clear ownership. One step at a time.' }}</h1><p>{{ zh ? '有序阶段支持单人、ALL 或 ANY 审批。已提交申请保留其原流程快照。' : 'Ordered stages support single, ALL or ANY review. Submitted requests keep their original process snapshot.' }}</p></div><KeepAlive><ProcessDesigner :key="s.activeScenarioId" v-if="s.draft" v-model="s.draft" :published="s.process" :expected-process-id="s.activeScenarioId" :people="s.people" :editable="s.me.id === 'alice'" :busy="s.busy" :publishing="s.publishing" :dirty="workspace.dirty()" :stale="workspace.stale()" :initial-locale="locale" :show-language="false" @publish="workspace.publish" @reset="workspace.resetDraft" /></KeepAlive></section>
